17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerEmailException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
36	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
37	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
38	import org.springframework.samples.petclinic.mapper.MembershipLevel;
39	import org.springframework.samples.petclinic.mapper.OwnerMapper;
40	import org.springframework.samples.petclinic.mapper.PetMapper;
41	import org.springframework.samples.petclinic.mapper.VisitMapper;
42	import org.springframework.samples.petclinic.model.Owner;
43	import org.springframework.samples.petclinic.model.Pet;
44	import org.springframework.samples.petclinic.model.Visit;
45	import org.springframework.samples.petclinic.rest.api.OwnersApi;
46	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
47	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.PetDto;
49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.util.StringUtils;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
73	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
74	     * addresses are lower-cased before being stored.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /**
80	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
81	     * named logger keeps them addressable independently of the class's diagnostic logging.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Maximum number of owners a single city may contain. A create that would take the owner's city
87	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
88	     */
89	    private static final int CITY_OWNER_LIMIT = 50;
90	
91	    /**
92	     * Maximum number of owners that may be registered on a single day. A create that would take the
93	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
94	     * have already been created that day - is rejected with a 429.
95	     */
96	    private static final int DAILY_OWNER_LIMIT = 100;
97	
98	    /**
99	     * Number of owners that must already have been created for a given day before the create
100	     * response flags a bulk sign-up. When more than this many owners already share a
101	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
102	     */
103	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
147	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
148	    }
149	
150	    /**
151	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
152	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
153	     * owner sign-ups.
154	     *
155	     * @param registrationDate the day to inspect, or {@code null}
156	     * @return {@code true} when more than the threshold of owners are registered on that day
157	     */
158	    private boolean isBulkSignupDay(LocalDate registrationDate) {
159	        return registrationDate != null
160	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
166	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
167	        validateRequiredFields(ownerFieldsDto);
168	        HttpHeaders headers = new HttpHeaders();
169	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
170	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
171	        owner.setEmail(normalizeEmail(owner.getEmail()));
172	        if (owner.getRegistrationDate() == null) {
173	            owner.setRegistrationDate(LocalDate.now());
174	        }
175	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
176	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
177	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
178	        }
179	        if (isDuplicateEmail(owner.getEmail())) {
180	            throw new DuplicateOwnerEmailException(owner.getEmail());
181	        }
182	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
183	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
184	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
185	        }
186	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
187	            throw new OwnerCityFullException(owner.getCity());
188	        }
189	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
190	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
191	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
192	        }
193	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
194	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
195	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
198	        this.clinicService.saveOwner(owner);
199	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
200	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
201	            MembershipLevel.forOwner(owner));
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
204	        headers.setLocation(UriComponentsBuilder.newInstance()
205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    /**
210	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
211	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
212	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
213	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
214	     * after normalization is still rejected.
215	     *
216	     * @param ownerFieldsDto the submitted owner fields
217	     */
218	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
219	        List<String> missingFields = new ArrayList<>();
220	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
221	            missingFields.add("firstName");
222	        }
223	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
224	            missingFields.add("lastName");
225	        }
226	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
227	            missingFields.add("address");
228	        }
229	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
230	            missingFields.add("city");
231	        }
232	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
233	            missingFields.add("telephone");
234	        }
235	        if (!missingFields.isEmpty()) {
236	            throw new MissingOwnerFieldsException(missingFields);
237	        }
238	    }
239	
240	    /**
241	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
242	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
243	     * address; the accepted value is lower-cased before it is stored and returned.
244	     *
245	     * @param email the raw email value submitted by the client, or {@code null}
246	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
247	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
248	     */
249	    private String normalizeEmail(String email) {
250	        if (!StringUtils.hasText(email)) {
251	            return email;
252	        }
253	        if (!EMAIL_PATTERN.matcher(email).matches()) {
254	            throw new InvalidOwnerFieldsException(List.of("email"));
255	        }
256	        return email.toLowerCase();
257	    }
258	
259	    /**
260	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
261	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
262	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
263	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
264	     *
265	     * @param city the owner's city
266	     * @param lastName the owner's last name
267	     * @return the assigned customer code
268	     */
269	    private String buildCustomerCode(String city, String lastName) {
270	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
271	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
272	        int sequence = (int) this.clinicService.findAllOwners().stream()
273	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
274	            .count() + 1;
275	        return String.format("%s-%s-%04d", city3, last3, sequence);
276	    }
277	
278	    /**
279	     * Determines whether an existing owner already shares a household with the supplied last name and
280	     * address. Two owners belong to the same household when {@link HouseholdNormalizer#sameHousehold}
281	     * considers their last name and address a match.
282	     *
283	     * @param lastName the submitted owner's last name
284	     * @param address the submitted owner's address
285	     * @return {@code true} if another owner already has the same normalized last name and address
286	     */
287	    /**
288	     * Counts how many owners already exist that share the supplied first and last name, compared
289	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
290	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
291	     *
292	     * @param firstName the submitted owner's first name
293	     * @param lastName the submitted owner's last name
294	     * @return the number of existing owners with the same first and last name, ignoring case
295	     */
296	    private int countNamesakes(String firstName, String lastName) {
297	        return (int) this.clinicService.findAllOwners().stream()
298	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
299	                && lastName.equalsIgnoreCase(existing.getLastName()))
300	            .count();
301	    }
302	
303	    /**
304	     * Determines whether an existing owner already uses the supplied email, compared by its
305	     * lower-cased form. Email is optional, so a missing or blank value is never considered a
306	     * duplicate. The submitted value has already been lower-cased by {@link #normalizeEmail}, and
307	     * every existing owner's email is compared case-insensitively.
308	     *
309	     * @param email the submitted owner's normalized email, or {@code null}
310	     * @return {@code true} if another owner already uses the same email, ignoring case
311	     */
312	    private boolean isDuplicateEmail(String email) {
313	        if (!StringUtils.hasText(email)) {
314	            return false;
315	        }
316	        return this.clinicService.findAllOwners().stream()
317	            .anyMatch(existing -> email.equalsIgnoreCase(existing.getEmail()));
318	    }
319	
320	    private boolean isDuplicateHousehold(String lastName, String address) {
321	        return this.clinicService.findAllOwners().stream()
322	            .anyMatch(existing -> HouseholdNormalizer.sameHousehold(
323	                lastName, address, existing.getLastName(), existing.getAddress()));
324	    }
325	
326	    /**
327	     * Counts how many existing owners already belong to the supplied household, identified by its
328	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
329	     * owner is added (this count plus one).
330	     *
331	     * @param householdId the normalized household identifier of the owner being created
332	     * @return the number of existing owners already sharing that {@code householdId}
333	     */
334	    private int countHouseholdMembers(String householdId) {
335	        return (int) this.clinicService.findAllOwners().stream()
336	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
337	            .count();
338	    }
339	
340	    /**
341	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
342	     * enforce the per-city capacity limit when a new owner is created.
343	     *
344	     * @param city the submitted owner's city
345	     * @return the number of existing owners in that city, ignoring case
346	     */
347	    private long countOwnersInCity(String city) {
348	        return this.clinicService.findAllOwners().stream()
349	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
350	            .count();
351	    }
352	
353	    /**
354	     * Counts how many owners have already been created on the supplied registration date. Used to
355	     * enforce the per-day capacity limit when a new owner is created.
356	     *
357	     * @param registrationDate the registration date of the owner being created
358	     * @return the number of existing owners already registered on that date
359	     */
360	    /**
361	     * Rolls a registration date forward to a business day. A registration date must fall on a
362	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
363	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
364	     * from the registration date (such as the membership number's year segment) and the daily
365	     * create-limit therefore use the adjusted date.
366	     *
367	     * @param date the effective registration date, whether supplied or defaulted to the server date
368	     * @return the same date when it is a weekday, otherwise the next Monday
369	     */
370	    private LocalDate toBusinessDay(LocalDate date) {
371	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
372	            date = date.plusDays(1);
373	        }
374	        return date;
375	    }
376	
377	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
378	        return this.clinicService.findAllOwners().stream()
379	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
380	            .count();
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
386	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
387	        if (currentOwner == null) {
388	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
389	        }
390	        currentOwner.setAddress(ownerFieldsDto.getAddress());
391	        currentOwner.setCity(ownerFieldsDto.getCity());
392	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
393	        currentOwner.setLastName(ownerFieldsDto.getLastName());
394	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
395	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
396	        this.clinicService.saveOwner(currentOwner);
397	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Transactional
402	    @Override
403	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
404	        Owner owner = this.clinicService.findOwnerById(ownerId);
405	        if (owner == null) {
406	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
407	        }
408	        this.clinicService.deleteOwner(owner);
409	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
410	    }
411	
